                    if value:
                        phase = (r + slope * c) % period
                        if phase in bands and bands[phase] != value:
                            valid = False
                            break
                        bands[phase] = value
                if not valid:
                    break
            if valid and len(bands) == period:
                return [[bands[(r + slope * c) % period] for c in range(w)]
                        for r in range(h)]
    # Conservative fallback for an incompletely specified pattern.
